"use client";

import { useState, useEffect } from "react";
import { discoverMovies, addMovie, getMovies } from "@/lib/api";

export default function DiscoverPage() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [added, setAdded] = useState<Record<string, boolean>>({});
  const [activeMovie, setActiveMovie] = useState<any | null>(null);
  const [friendInput, setFriendInput] = useState("");
  const [saving, setSaving] = useState(false);
  const [existingIds, setExistingIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    const loadExisting = async () => {
        const movies = await getMovies();
        const ids = new Set<string>(movies.map((m: any) => m.imdb_id as string));
        setExistingIds(ids);
        setAdded(Object.fromEntries(Array.from(ids).map(id => [id, true])));
    };
    loadExisting();
    }, []);


  const search = async () => {
    setLoading(true);
    const data = await discoverMovies(query);
    setResults(data);
    setLoading(false);
  };

  return (
    <main style={{ padding: 24 }}>
      <h1>🔍 Discover</h1>

      <input
        placeholder="Search movie..."
        value={query}
        onChange={e => setQuery(e.target.value)}
        style={{ padding: 8, marginRight: 8 }}
      />

      <button onClick={search}>Search</button>

      {loading && <p>Loading...</p>}

      <div style={{ marginTop: 24 }}>
        {results.map((movie, index) => {
            const isAdded = added[movie.external_id] || existingIds.has(movie.external_id);

            return (
                <div
                key={`${movie.external_id}-${index}`}
                style={{
                    display: "flex",
                    gap: 16,
                    marginBottom: 16,
                    border: "1px solid #444",
                    padding: 12,
                }}
                >
                {movie.image_url && (
                    <img
                    src={movie.image_url}
                    alt={movie.title}
                    width={80}
                    style={{ borderRadius: 4 }}
                    />
                )}

                <div>
                    <h3>{movie.title}</h3>
                    <p style={{ opacity: 0.6 }}>
                    {movie.year} - {movie.external_id}
                    </p>

                    <button
                    onClick={() => setActiveMovie(movie)}
                    disabled={isAdded}
                    style={{
                        marginTop: 8,
                        padding: "6px 10px",
                        cursor: isAdded ? "not-allowed" : "pointer",
                        opacity: isAdded ? 0.6 : 1,
                    }}
                    >
                    {isAdded ? "Added ✓" : "Add to WatchPop"}
                    </button>
                </div>
                </div>
            );
            })}
      </div>
        {activeMovie && (
            <div
                style={{
                position: "fixed",
                inset: 0,
                background: "rgba(0,0,0,0.6)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                zIndex: 50,
                }}
            >
                <div
                style={{
                    background: "#111",
                    padding: 20,
                    width: 400,
                    borderRadius: 8,
                }}
                >
                <h3>Add to WatchPop</h3>
                <p style={{ opacity: 0.7 }}>
                    Who recommended <b>{activeMovie.title}</b>?
                </p>

                <input
                    placeholder="Friend names (comma-separated)"
                    value={friendInput}
                    onChange={e => setFriendInput(e.target.value)}
                    style={{ width: "100%", padding: 8, marginTop: 10 }}
                />

                <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
                    <button
                    onClick={() => {
                        setActiveMovie(null);
                        setFriendInput("");
                    }}
                    >
                    Cancel
                    </button>

                    <button
                    disabled={saving}
                    onClick={async () => {
                        setSaving(true);

                        const friendTags = friendInput
                        .split(",")
                        .map(t => t.trim())
                        .filter(Boolean); // ✅ ensures string[]

                        await addMovie(activeMovie.external_id, friendTags);
                        setExistingIds(prev => new Set(prev).add(activeMovie.external_id));

                        setAdded(prev => ({
                            ...prev,
                            [activeMovie.external_id]: true,
                        }));
                        setSaving(false);
                        setActiveMovie(null);
                        setFriendInput("");
                    }}
                    >
                    {saving ? "Saving..." : "Save"}
                    </button>
                </div>
                </div>
            </div>
        )}
    </main>
  );
}
